package com.vahotel.service;
import com.vahotel.model.OtpToken;import com.vahotel.repo.OtpTokenRepository;import java.security.SecureRandom;import java.time.LocalDateTime;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;
@Service public class OtpService {private final OtpTokenRepository repo;private final PasswordEncoder encoder;private final EmailNotificationService email;private final SecureRandom random=new SecureRandom();@Value("${va.hotel.otp.log-to-console:true}") private boolean logOtp;
 public OtpService(OtpTokenRepository r,PasswordEncoder e,EmailNotificationService email){repo=r;encoder=e;this.email=email;}
 public boolean send(String recipient){String code=String.format("%06d",random.nextInt(1_000_000));repo.findTopByEmailAndUsedFalseOrderByIdDesc(recipient).ifPresent(t->{t.setUsed(true);repo.save(t);});repo.save(new OtpToken(recipient,encoder.encode(code),LocalDateTime.now().plusMinutes(10)));boolean emailed=email.sendOtp(recipient,code);if(!emailed&&logOtp)System.out.println("VA HOTEL DEVELOPMENT OTP for "+recipient+": "+code);return emailed;}
 public boolean verify(String email,String code){var found=repo.findTopByEmailAndUsedFalseOrderByIdDesc(email);if(found.isEmpty()||found.get().getExpiresAt().isBefore(LocalDateTime.now())||!encoder.matches(code,found.get().getCodeHash()))return false;found.get().setUsed(true);repo.save(found.get());return true;}}
